"""Parsing utilities for HPLC/GC instrument CSV exports."""
from __future__ import annotations

import csv
from typing import Iterator, Dict


def parse_assay_value(raw: str) -> float:
    """Parse a numeric assay/impurity result from an instrument export field.

    Instrument exports are period-decimal (US/UK locale) by default, e.g.
    '98.5'. Returns NaN for blank or non-numeric fields (e.g. 'N/A').
    """
    raw = raw.strip()
    if raw == "" or raw.upper() in ("N/A", "NA"):
        return float("nan")
    try:
        return float(raw)
    except ValueError:
        return float("nan")


def load_batch_rows(path: str) -> Iterator[Dict[str, str]]:
    with open(path, newline="") as f:
        reader = csv.DictReader(f)
        for row in reader:
            yield row

