package com.rakuten.pay.refund;

import org.springframework.web.bind.annotation.*;
import org.springframework.http.ResponseEntity;

@RestController
@RequestMapping("/refunds")
public class RefundController {

    private final RefundService refundService;

    public RefundController(RefundService refundService) {
        this.refundService = refundService;
    }

    @PostMapping("/{orderId}")
    public ResponseEntity<RefundResult> requestRefund(@PathVariable String orderId,
                                                        @RequestBody RefundRequest req) {
        RefundResult result = refundService.processRefund(
                req.getMerchantId(), orderId, req.getAmountMinorUnits(), RefundSource.API_DIRECT);
        return ResponseEntity.ok(result);
    }

    // New in this PR: merchant dashboard "Retry Refund" button.
    // Hits the same processRefund() path but tagged as MERCHANT_DASHBOARD_RETRY
    // so we can track retry-originated refunds separately in the ledger.
    @PostMapping("/{orderId}/retry")
    public ResponseEntity<RefundResult> retryRefund(@PathVariable String orderId,
                                                      @RequestBody RefundRequest req) {
        RefundResult result = refundService.processRefund(
                req.getMerchantId(), orderId, req.getAmountMinorUnits(), RefundSource.MERCHANT_DASHBOARD_RETRY);
        return ResponseEntity.ok(result);
    }

    @GetMapping("/{orderId}/status")
    public ResponseEntity<RefundStatus> getStatus(@PathVariable String orderId) {
        return ResponseEntity.ok(refundService.getStatus(orderId));
    }
}

package com.rakuten.pay.refund;

import org.springframework.stereotype.Service;

@Service
public class RefundService {

    private final IdempotencyStore idempotencyStore;
    private final PaymentProcessorClient paymentProcessorClient;
    private final LedgerService ledgerService;

    public RefundService(IdempotencyStore idempotencyStore,
                          PaymentProcessorClient paymentProcessorClient,
                          LedgerService ledgerService) {
        this.idempotencyStore = idempotencyStore;
        this.paymentProcessorClient = paymentProcessorClient;
        this.ledgerService = ledgerService;
    }

    public RefundResult processRefund(String merchantId, String orderId, long amountMinorUnits, RefundSource source) {
        String idempotencyKey = IdempotencyKeyGenerator.generate(merchantId, orderId, source);

        // Dedupe: if we've already processed a refund under this exact idempotency
        // key, return the cached result instead of hitting the processor again.
        if (idempotencyStore.exists(idempotencyKey)) {
            return idempotencyStore.get(idempotencyKey);
        }

        RefundResult result = paymentProcessorClient.refund(merchantId, orderId, amountMinorUnits);
        idempotencyStore.put(idempotencyKey, result);
        ledgerService.recordRefund(orderId, amountMinorUnits, source);
        return result;
    }

    public RefundStatus getStatus(String orderId) {
        return ledgerService.getStatus(orderId);
    }
}

package com.rakuten.pay.refund;

import org.apache.commons.codec.digest.DigestUtils;
import java.util.UUID;

public class IdempotencyKeyGenerator {

    /**
     * Generates an idempotency key used to dedupe refund requests before they
     * reach the payment processor.
     *
     * NOTE (kfujimori, 2026-07-18): MERCHANT_DASHBOARD_RETRY currently generates
     * a fresh random key per call instead of reusing/deriving a stable key. This
     * was a shortcut to ship the retry-button feature for 3.4 without touching the
     * shared idempotency store schema (that migration is riskier and slower - see
     * PAY-4821 for the real fix: order-level distributed lock + deterministic key
     * across all sources, targeted for 3.5). Reconciliation job PAY-3190 runs
     * nightly and cross-checks the processor's settlement file against our ledger,
     * so any double-post here should surface within 24h for manual reversal.
     */
    public static String generate(String merchantId, String orderId, RefundSource source) {
        switch (source) {
            case MERCHANT_DASHBOARD_RETRY:
                return UUID.randomUUID().toString();
            case DISPUTE_AUTOMATION:
            case API_DIRECT:
            default:
                return DigestUtils.sha256Hex(merchantId + ":" + orderId);
        }
    }
}

